(7513239, 1199498, 28742, '<td valign="top">Looks too fake. :P Kidding. :)</td>', 'Looks too fake. :P Kidding. :)', '2017-05-11 23:55:59.000000', NULL, 1),
(7513241, 1199535, 28742, '<td valign="top">Good work on this! Blending the building and the dog into the scene could use some improvement - mostly lighting related I think. Great effort and solid result, though. Good luck!</td>', 'Good work on this! Blending the building and the dog into the scene could use some improvement - mostly lighting related I think. Great effort and solid result, though. Good luck!', '2017-05-11 23:58:56.000000', NULL, 1),
